create function public.cart_set(p_service uuid,p_quantity integer)returns void language plpgsql security definer set search_path=public as $$declare u uuid:=public.assert_user();c uuid;begin perform public.rate_limit('cart:'||u,120,60);if p_quantity not between 0 and 100 then raise exception 'Neispravna količina';end if;insert into public.carts(user_id)values(u)on conflict(user_id)do update set user_id=excluded.user_id returning id into c;if p_quantity=0 then delete from public.cart_items where cart_id=c and service_id=p_service;else if not exists(select 1 from public.services where id=p_service and active and price_cents is not null)then raise exception 'Usluga zahtijeva ponudu';end if;insert into public.cart_items(cart_id,service_id,quantity)values(c,p_service,p_quantity)on conflict(cart_id,service_id)do update set quantity=excluded.quantity;end if;end$$;
create function public.create_order(p_service uuid,p_quantity integer,p_title text,p_description text,p_due timestamptz default null,p_model text default 'full',p_promo text default null)returns uuid language plpgsql security definer set search_path=public as $$declare u uuid:=public.assert_user();s public.services;v_total integer;oid uuid;promo public.promo_codes;d integer;begin perform public.rate_limit('order:'||u,20,3600);if p_quantity not between 1 and 100 or p_model not in('full','split') then raise exception 'Neispravan zahtjev';end if;if p_due is not null and p_due<=now() then raise exception 'Rok mora biti u budućnosti';end if;select * into s from public.services where id=p_service and active for share;if not found then raise exception 'Usluga nije dostupna';end if;v_total:=s.price_cents*p_quantity;if v_total>100000000 then raise exception 'Iznos je previsok';end if;if p_promo is not null and p_promo<>'' then select * into promo from public.promo_codes where code=upper(trim(p_promo)) for update;if not found or not promo.active or promo.expires_at<=now()or(promo.service_id is not null and promo.service_id<>s.id)or v_total is null then raise exception 'Kupon nije primjenjiv';end if;if exists(select 1 from public.promo_code_uses where promo_id=promo.id and user_id=u)or(select count(*)from public.promo_code_uses where promo_id=promo.id)>=promo.max_uses then raise exception 'Kupon je iskorišten';end if;d:=case when promo.kind='fixed' then promo.value else floor(v_total::numeric*promo.value/100)::int end;v_total:=greatest(0,v_total-d);if v_total<100 then raise exception 'Najmanji iznos nakon popusta je 1 EUR';end if;end if;if p_model='split' and(v_total is null or not s.split_enabled or v_total<s.split_min_cents)then raise exception '50/50 nije dostupno';end if;insert into public.orders(user_id,title,description,total_cents,payment_model,due_at,status)values(u,trim(p_title),trim(p_description),v_total,p_model,p_due,case when v_total is null then 'quote_pending'::public.order_state else 'deposit_pending'::public.order_state end)returning id into oid;insert into public.order_items(order_id,service_id,name,quantity,unit_cents)values(oid,s.id,s.name,p_quantity,s.price_cents);if v_total is not null then insert into public.payment_installments(order_id,installment,amount_cents)values(oid,1,case when p_model='split' then(v_total+1)/2 else v_total end);if p_model='split' then insert into public.payment_installments(order_id,installment,amount_cents)values(oid,2,v_total/2);end if;end if;if promo.id is not null then insert into public.promo_code_uses(promo_id,user_id,order_id)values(promo.id,u,oid);end if;return oid;end$$;
create function public.checkout_cart(p_description text,p_model text default 'full')returns uuid[] language plpgsql security definer set search_path=public as $$declare u uuid:=public.assert_user();c uuid;r record;ids uuid[]:='{}';begin select id into c from public.carts where user_id=u for update;if c is null then raise exception 'Košarica je prazna';end if;for r in select ci.*,s.name from public.cart_items ci join public.services s on s.id=ci.service_id where cart_id=c order by ci.id for update of ci loop ids:=array_append(ids,public.create_order(r.service_id,r.quantity,r.name,p_description,null,p_model,null));end loop;if cardinality(ids)=0 then raise exception 'Košarica je prazna';end if;delete from public.cart_items where cart_id=c;return ids;end$$;
create function public.send_message(p_order uuid,p_body text,p_internal boolean default false)returns void language plpgsql security definer set search_path=public as $$declare u uuid:=public.assert_user();n uuid;owner_id uuid;begin if not(public.is_admin()or public.owns_order(p_order))or(p_internal and not public.is_admin())then raise exception 'Nemate pristup razgovoru';end if;perform public.rate_limit('message:'||u,30,60);insert into public.order_messages(order_id,sender_id,body,internal)values(p_order,u,trim(p_body),p_internal);if public.is_admin()and not p_internal then select user_id into owner_id from public.orders where id=p_order;insert into public.notifications(user_id,title,body)values(owner_id,'Nova poruka','Otvorite razgovor narudžbe za pregled poruke.')returning id into n;insert into public.notification_outbox(user_id,notification_id)values(owner_id,n);end if;end$$;
create function public.create_quote(p_order uuid,p_description text,p_total integer,p_expires timestamptz,p_due timestamptz,p_split boolean default false)returns uuid language plpgsql security definer set search_path=public as $$declare o public.orders;qid uuid;v integer;begin perform public.assert_admin();select * into o from public.orders where id=p_order for update;if not found or o.status not in('quote_pending','quote_sent','received')or o.paid_cents>0 then raise exception 'Ponuda se ne može promijeniti';end if;if p_expires<=now()or p_due<=p_expires then raise exception 'Provjerite rokove ponude';end if;select coalesce(max(version),0)+1 into v from public.quotes where order_id=p_order;insert into public.quotes(order_id,version,description,total_cents,expires_at,due_at,split_enabled)values(p_order,v,p_description,p_total,p_expires,p_due,p_split)returning id into qid;update public.orders set status='quote_sent' where id=p_order;return qid;end$$;
create function public.accept_quote(p_quote uuid,p_model text default 'full')returns void language plpgsql security definer set search_path=public as $$declare q public.quotes;o public.orders;begin perform public.assert_user();select * into q from public.quotes where id=p_quote;if not found then raise exception 'Ponuda ne postoji';end if;select * into o from public.orders where id=q.order_id for update;select * into q from public.quotes where id=p_quote for update;if o.user_id<>auth.uid()or o.status<>'quote_sent'or q.accepted_at is not null or q.rejected_at is not null or q.expires_at<=now()or q.version<>(select max(version)from public.quotes where order_id=q.order_id)then raise exception 'Ponuda nije važeća';end if;if p_model not in('full','split')or(p_model='split'and(not q.split_enabled or q.total_cents<200))then raise exception 'Model plaćanja nije dostupan';end if;update public.quotes set accepted_at=now()where id=q.id;update public.orders set total_cents=q.total_cents,payment_model=p_model,due_at=q.due_at,status='deposit_pending' where id=q.order_id;insert into public.payment_installments(order_id,installment,amount_cents)values(q.order_id,1,case when p_model='split'then(q.total_cents+1)/2 else q.total_cents end);if p_model='split'then insert into public.payment_installments(order_id,installment,amount_cents)values(q.order_id,2,q.total_cents/2);end if;end$$;
create function public.reject_quote(p_quote uuid)returns void language plpgsql security definer set search_path=public as $$declare q public.quotes;begin select * into q from public.quotes where id=p_quote for update;if not public.owns_order(q.order_id)or q.accepted_at is not null then raise exception 'Ponuda nije dostupna';end if;perform 1 from public.orders where id=q.order_id for update;update public.quotes set rejected_at=now()where id=q.id;update public.orders set status='quote_pending'where id=q.order_id and status='quote_sent';end$$;
create function public.transition_order(p_order uuid,p_status public.order_state)returns void language plpgsql security definer set search_path=public as $$declare o public.orders;allowed boolean;begin perform public.assert_admin();select * into o from public.orders where id=p_order for update;allowed:=case o.status when'received'then p_status in('quote_pending','cancelled')when'quote_pending'then p_status='cancelled'when'quote_sent'then p_status='cancelled'when'deposit_pending'then p_status='cancelled'when'ready'then p_status in('in_progress','cancelled')when'in_progress'then p_status in('needs_info','work_done','cancelled')when'needs_info'then p_status in('in_progress','cancelled')when'work_done'then p_status in('final_pending','delivered')when'delivered'then p_status in('revision','completed')when'revision'then p_status='in_progress'else false end;if not coalesce(allowed,false)then raise exception 'Nedopušten prijelaz statusa';end if;if p_status='cancelled'and o.paid_cents>0 then raise exception 'Prvo riješite povrat uplate';end if;if p_status='delivered'and(o.total_cents is null or o.paid_cents<o.total_cents)then raise exception 'Završna uplata nije potvrđena';end if;if p_status='final_pending'and(o.payment_model<>'split'or o.paid_cents>=o.total_cents)then raise exception 'Završna uplata nije potrebna';end if;update public.orders set status=p_status where id=p_order;end$$;
create function public.open_ticket(p_subject text,p_category text,p_body text)returns uuid language plpgsql security definer set search_path=public as $$declare u uuid:=public.assert_user();tid uuid;begin perform public.rate_limit('ticket:'||u,10,3600);insert into public.support_tickets(user_id,subject,category,body)values(u,p_subject,p_category,p_body)returning id into tid;return tid;end$$;
create function public.reply_ticket(p_ticket uuid,p_body text,p_close boolean default false)returns void language plpgsql security definer set search_path=public as $$begin if not exists(select 1 from public.support_tickets where id=p_ticket and(user_id=public.assert_user()or public.is_admin()))then raise exception 'Nemate pristup zahtjevu';end if;if p_close then perform public.assert_admin();update public.support_tickets set status='closed'where id=p_ticket;end if;perform public.rate_limit('reply:'||auth.uid(),30,60);insert into public.support_messages(ticket_id,sender_id,body)values(p_ticket,auth.uid(),p_body);end$$;
-- Funkcije dostupne samo service_roleu (Edge Functions); ne vjeruju klijentskim iznosima.
create function public.reserve_payment(p_order uuid,p_user uuid)returns public.payments language plpgsql security definer set search_path=public as $$declare o public.orders;p public.payments;i public.payment_installments;a integer;begin if not exists(select 1 from public.site_settings where stripe_enabled and not maintenance)then raise exception 'Plaćanje nije aktivirano';end if;select * into o from public.orders where id=p_order and user_id=p_user for update;if not found or o.total_cents is null then raise exception 'Narudžba nije dostupna za plaćanje';end if;if o.status not in('deposit_pending','final_pending')then raise exception 'Uplata trenutačno nije potrebna';end if;select * into i from public.payment_installments where order_id=o.id and installment=case when o.status='final_pending'then 2 else 1 end;if not found or i.amount_cents<1 then raise exception 'Plan plaćanja ne postoji';end if;select * into p from public.payments where order_id=o.id and installment=i.installment and status in('pending','succeeded','partially_refunded','refunded');if found then if p.status<>'pending'then raise exception 'Uplata je već obrađena';end if;return p;end if;select coalesce(max(attempt),0)+1 into a from public.payments where order_id=o.id and installment=i.installment;insert into public.payments(order_id,installment,amount_cents,attempt)values(o.id,i.installment,i.amount_cents,a)returning * into p;return p;end$$;
create function public.apply_stripe_event(p_event text,p_type text,p_payment uuid,p_session text,p_intent text,p_amount integer,p_currency text,p_status text,p_refunded integer default 0,p_fee integer default null)returns void language plpgsql security definer set search_path=public as $$declare p public.payments;inserted text;net_paid integer;begin insert into public.payment_provider_events(id,provider,type)values(p_event,'stripe',p_type)on conflict do nothing returning id into inserted;if inserted is null then return;end if;select * into p from public.payments where id=p_payment for update;if not found or p.provider<>'stripe'or p.amount_cents<>p_amount or p_currency<>'eur'or(p.provider_session_id is not null and p.provider_session_id<>p_session)or(p.provider_payment_id is not null and p.provider_payment_id is distinct from p_intent)then raise exception 'Podaci uplate se ne podudaraju';end if;if p_status not in('succeeded','failed','expired','refunded','partially_refunded')then raise exception 'Neispravan status';end if;if p_status in('failed','expired')and p.status<>'pending'then return;end if;if p_status='succeeded'and p.status in('refunded','partially_refunded')then return;end if;if p_refunded<p.refunded_cents then return;end if;update public.payments set status=p_status,provider_session_id=coalesce(provider_session_id,p_session),provider_payment_id=coalesce(provider_payment_id,p_intent),refunded_cents=p_refunded,fee_cents=coalesce(p_fee,fee_cents)where id=p.id;perform 1 from public.orders where id=p.order_id for update;select coalesce(sum(amount_cents-refunded_cents),0)into net_paid from public.payments where order_id=p.order_id and status in('succeeded','refunded','partially_refunded');update public.orders set paid_cents=net_paid,status=case when status='deposit_pending'and net_paid>=(select amount_cents from public.payment_installments where order_id=p.order_id and installment=1)then 'ready'::public.order_state when status='final_pending'and net_paid>=total_cents then 'delivered'::public.order_state else status end where id=p.order_id;end$$;
create function public.submit_contact(p_name text,p_email text,p_body text,p_client text)returns void language plpgsql security definer set search_path=public as $$begin perform public.rate_limit('contact:'||p_client,5,3600);insert into public.contact_requests(name,email,body)values(p_name,p_email,p_body);end$$;
-- Supabase ponajprije dodjeljuje EXECUTE PUBLIC-u: zatvoriti sve funkcije pa otvoriti samo potrebne.
revoke execute on all functions in schema public from public,anon,authenticated;
grant execute on function public.is_admin(),public.owns_order(uuid)to anon,authenticated;
grant execute on function public.cart_set(uuid,integer),public.create_order(uuid,integer,text,text,timestamptz,text,text),public.checkout_cart(text,text),public.send_message(uuid,text,boolean),public.create_quote(uuid,text,integer,timestamptz,timestamptz,boolean),public.accept_quote(uuid,text),public.reject_quote(uuid),public.transition_order(uuid,public.order_state),public.open_ticket(text,text,text),public.reply_ticket(uuid,text,boolean)to authenticated;
grant all on all tables in schema public to service_role;
grant all on all sequences in schema public to service_role;
grant execute on all functions in schema public to service_role;
